public class Main {
    public static void main(String[] args) {
        BankAccount account = new BankAccount(1000);

        account.deposit(500);   // valid: balance becomes 1500
        account.withdraw(2000); // invalid: exceeds balance, rejected
        account.withdraw(300);  // valid: balance becomes 1200

        System.out.println("Final balance: " + account.getBalance());
    }
}

// BankAccount enforces its own rules, nobody outside can bypass them
class BankAccount {
    private double balance; // hidden: cannot be touched directly from outside

    public BankAccount(double initialBalance) {
        if (initialBalance < 0) {
            throw new IllegalArgumentException("Initial balance cannot be negative");
        }
        this.balance = initialBalance;
    }

    public void deposit(double amount) {
        if (amount <= 0) { // reject nonsense input before it corrupts state
            System.out.println("Deposit rejected: amount must be positive");
            return;
        }
        balance += amount;
        System.out.println("Deposited " + amount + ", balance now " + balance);
    }

    public void withdraw(double amount) {
        if (amount > balance) { // the core invariant: balance can never go negative
            System.out.println("Withdrawal rejected: insufficient funds");
            return;
        }
        balance -= amount;
        System.out.println("Withdrew " + amount + ", balance now " + balance);
    }

    public double getBalance() {
        return balance; // read-only access, no public setter exists at all
    }
}

