#include <iostream>
#include <stdexcept>
using namespace std;

// BankAccount enforces its own rules, nobody outside can bypass them
class BankAccount {
private:
    double balance; // hidden: cannot be touched directly from outside

public:
    BankAccount(double initialBalance) {
        if (initialBalance < 0) {
            throw invalid_argument("Initial balance cannot be negative");
        }
        balance = initialBalance;
    }

    void deposit(double amount) {
        if (amount <= 0) { // reject nonsense input before it corrupts state
            cout << "Deposit rejected: amount must be positive" << endl;
            return;
        }
        balance += amount;
        cout << "Deposited " << amount << ", balance now " << balance << endl;
    }

    void withdraw(double amount) {
        if (amount > balance) { // the core invariant: balance can never go negative
            cout << "Withdrawal rejected: insufficient funds" << endl;
            return;
        }
        balance -= amount;
        cout << "Withdrew " << amount << ", balance now " << balance << endl;
    }

    double getBalance() {
        return balance; // read-only access, no public setter exists at all
    }
};

int main() {
    BankAccount account(1000);

    account.deposit(500);   // valid: balance becomes 1500
    account.withdraw(2000); // invalid: exceeds balance, rejected
    account.withdraw(300);  // valid: balance becomes 1200

    cout << "Final balance: " << account.getBalance() << endl;
    return 0;
}
